function pushWord(out:number[],value:number){out.push(value&255,(value>>8)&255)}
function palette(){const out:number[]=[];for(let i=0;i<256;i++){const r=(i>>5)&7,g=(i>>2)&7,b=i&3;out.push(Math.round(r*255/7),Math.round(g*255/7),Math.round(b*255/3))}return out}
function indices(data:Uint8ClampedArray){const out=new Uint8Array(data.length/4);for(let i=0,j=0;i<data.length;i+=4,j++)out[j]=((data[i]>>5)<<5)|((data[i+1]>>5)<<2)|(data[i+2]>>6);return out}
function lzw(input:Uint8Array){const clear=256,end=257,out:number[]=[];let buffer=0,bits=0,size=9,next=258,hasPrevious=false;const emit=(code:number)=>{buffer|=code<<bits;bits+=size;while(bits>=8){out.push(buffer&255);buffer>>>=8;bits-=8}};emit(clear);for(const value of input){emit(value);if(hasPrevious){next++;if(next===(1<<size)&&size<12)size++;if(next>=4095){emit(clear);size=9;next=258;hasPrevious=false;continue}}hasPrevious=true}emit(end);if(bits)out.push(buffer&255);return out}
export function encodeStaticGif(image:ImageData){const width=image.width,height=image.height,out:number[]=[...new TextEncoder().encode('GIF89a')];pushWord(out,width);pushWord(out,height);out.push(0xf7,0,0,...palette(),0x21,0xf9,4,0,0,0,0,0,0x2c);pushWord(out,0);pushWord(out,0);pushWord(out,width);pushWord(out,height);out.push(0,8);const data=lzw(indices(image.data));for(let i=0;i<data.length;i+=255){const block=data.slice(i,i+255);out.push(block.length,...block)}out.push(0,0x3b);return new Uint8Array(out)}
